  text = text.replace(/<(div|span|table)\b[^>]*(?:class|id)\s*=\s*["'][^"']*(?:gmail_signature|moz-signature|signature)[^"']*["'][^>]*>[\s\S]*$/gi, () => {
    signatureRemoved = true;
    return '';
